#!/usr/bin/env bash
# منبع واحد حقیقت (single source of truth) برای فایل‌های حیاتیِ امنیتی در
# دیپلوی staging. این فایل توسط چند مرحله در deploy-staging.yml source
# می‌شود تا لیست فقط یک‌ بار تعریف شود:
#
#   - مسیرهای این آرایه از mirror اصلی lftp حذف (exclude) می‌شوند — یعنی
#     هرگز مشمول هیوریستیک skip بر پایه اندازه/زمان lftp نمی‌شوند.
#   - همین مسیرها بلافاصله بعد از mirror با `put` صریح (نه mirror) و به‌صورت
#     اجباری آپلود می‌شوند — `put` هیچ منطق skip ندارد، همیشه ارسال می‌کند.
#   - همین مسیرها بعد از آپلود با hash SHA256 در برابر آرتیفکت CI و در برابر
#     محتوای واقعی سرور راستی‌آزمایی می‌شوند.
#
# افزودن فایل حیاتی جدید در آینده فقط به یک تغییر در همین آرایه نیاز دارد؛
# هیچ مرحله‌ای در ورک‌فلو نباید این لیست را به‌صورت جداگانه hardcode کند.
CRITICAL_DEPLOY_FILES=(
  "localized/.csp-release.json"
  "public/locales/csp-manifest.json"
)
